import {form,number as num,select as sel,result,n} from '../ui.mjs';
import {budgetTotals,subscriptionTotals,debtPlan,unitPrice,cashFlow} from './plus-core.mjs';
import {recordForm} from './record-form.mjs';
import {table,exportCSV} from './shared.mjs';
const currency=()=>sel('currency','Currency label',['NPR','USD','EUR','GBP','INR','AUD'],'NPR');
const money=(value,code)=>code+' '+(value/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
const lines=(data,ids)=>data.map(row=>ids.map(id=>String(row[id])).join(' | ')).join('\n');
export function setupMoneyPlus(tool,mount,out){
 if(tool.id==='budget-planner')return recordForm(mount,{columns:[{id:'name',label:'Category'},{id:'planned',label:'Planned',type:'number',min:0},{id:'actual',label:'Actual',type:'number',min:0}],initial:[{name:'Housing',planned:12000,actual:12000},{name:'Food',planned:6000,actual:6500},{name:'Transport',planned:2000,actual:1800}],fields:[num('income','Monthly income',30000,0,1e10),currency()],saveKey:'nepocore-budget-v1',label:'Calculate budget',note:'One currency, no bank connection. Local saving is optional; export a backup if you need one.',run:(data,v)=>{const r=budgetTotals(v.income,lines(data,['name','planned','actual']));result(out,{label:'Remaining after actual spending',value:money(r.actualLeft,v.currency),details:[['Planned remaining',money(r.plannedLeft,v.currency)],['Actual expenses',money(r.actual,v.currency)],['Income',money(r.income,v.currency)]],html:table(['Category','Planned','Actual','Actual − planned'],r.list.map(x=>[x.name,money(x.planned,v.currency),money(x.actual,v.currency),money(x.actual-x.planned,v.currency)])),note:'Negative remaining cash means these entered expenses exceed the entered income.'});exportCSV(out,r.list.map(x=>({category:x.name,planned:x.planned/100,actual:x.actual/100,currency:v.currency})),'nepocore-budget.csv');}});
 if(tool.id==='subscription-tracker')return recordForm(mount,{columns:[{id:'name',label:'Subscription'},{id:'price',label:'Price per bill',type:'number',min:0},{id:'cycle',label:'Billing cycle',options:['weekly','fortnightly','monthly','quarterly','yearly'],value:'monthly'}],initial:[{name:'Service A',price:499,cycle:'monthly'},{name:'Annual plan',price:2400,cycle:'yearly'},{name:'Weekly membership',price:120,cycle:'weekly'}],fields:[currency()],saveKey:'nepocore-subscriptions-v1',label:'Compare yearly costs',note:'Annualized averages use 52 weeks, 26 fortnights, 12 months or four quarters. Dates and renewal prices can differ.',run:(data,v)=>{const r=subscriptionTotals(lines(data,['name','price','cycle']));result(out,{label:'Annualized total',value:money(r.annual,v.currency),details:[['Average per month',money(r.monthly,v.currency)],['Subscriptions',r.list.length]],html:table(['Service','Billing','Annualized'],r.list.map(x=>[x.name,money(x.price,v.currency)+' / '+x.cycle,money(x.annual,v.currency)]))});exportCSV(out,r.list.map(x=>({name:x.name,price:x.price/100,cycle:x.cycle,annual:x.annual/100,currency:v.currency})),'nepocore-subscriptions.csv');}});
 if(tool.id==='debt-payoff')return recordForm(mount,{columns:[{id:'name',label:'Debt name'},{id:'balance',label:'Balance',type:'number',min:.01},{id:'apr',label:'APR %',type:'number',min:0,max:100},{id:'minimum',label:'Monthly minimum',type:'number',min:.01}],initial:[{name:'Debt A',balance:10000,apr:12,minimum:1000},{name:'Debt B',balance:5000,apr:18,minimum:600}],fields:[num('extra','Extra per month',500,0,1e9),sel('strategy','Priority',[['avalanche','Highest APR first'],['snowball','Smallest balance first']],'avalanche'),currency()],label:'Model repayment',note:'Fixed APR/12 monthly interest, month-end payments, no new borrowing or fees. The total payment budget is retained as debts finish.',run:(data,v)=>{const input=lines(data,['name','balance','apr','minimum']),r=debtPlan(input,+v.extra,v.strategy),other=debtPlan(input,+v.extra,v.strategy==='snowball'?'avalanche':'snowball');result(out,{label:'Modeled payoff time',value:r.months+' months',details:[['Modeled interest',money(r.totalInterest,v.currency)],['Total paid',money(r.totalPaid,v.currency)],['Monthly budget',money(r.monthlyBudget,v.currency)],['Other strategy',other.months+' months; '+money(other.totalInterest,v.currency)+' interest']],html:table(['Month','Payment','Interest','Remaining'],r.schedule.slice(0,24).map(x=>[x.month,money(x.paid,v.currency),money(x.interest,v.currency),money(x.remaining,v.currency)])),note:'The first 24 months are shown. The CSV includes the complete model. Actual lender calculations may differ.'});exportCSV(out,r.schedule.map(x=>({month:x.month,payment:x.paid/100,interest:x.interest/100,remaining:x.remaining/100,currency:v.currency})),'nepocore-debt-model.csv');}});
 if(tool.id==='unit-price')return form(mount,[currency(),num('priceA','Product A price',240,0,1e9),num('quantityA','Product A quantity',750,.000001,1e9),sel('unitA','Product A unit',['g','kg','ml','l','cm','m','each'],'g'),num('discountA','Product A discount %',0,0,100),num('priceB','Product B price',300,0,1e9),num('quantityB','Product B quantity',1,.000001,1e9),sel('unitB','Product B unit',['g','kg','ml','l','cm','m','each'],'kg'),num('discountB','Product B discount %',0,0,100)],v=>{const a=unitPrice(v.priceA,v.quantityA,v.unitA,v.discountA),b=unitPrice(v.priceB,v.quantityB,v.unitB,v.discountB);if(a.family!==b.family)throw Error('Compare units from the same measurement family.');const factor=['mass','volume'].includes(a.family)?1000:1,label={mass:'kg',volume:'litre',length:'metre',count:'item'}[a.family],equal=Math.abs(a.perBase-b.perBase)<1e-10,cheaper=a.perBase<b.perBase?'Product A':'Product B';result(out,{label:'Lower unit price',value:equal?'Equal unit prices':cheaper,details:[['Product A',money(a.perBase*factor,v.currency)+' per '+label],['Product B',money(b.perBase*factor,v.currency)+' per '+label],['Difference',money(Math.abs(a.perBase-b.perBase)*factor,v.currency)+' per '+label]],note:'The comparison uses entered prices and discounts. Quality, delivery and other fees are separate.'});},{label:'Compare unit prices'});
}
export function cashFlowTool(mount,out){return recordForm(mount,{columns:[{id:'period',label:'Period'},{id:'receipts',label:'Cash receipts',type:'number',min:0},{id:'payments',label:'Cash payments',type:'number',min:0}],initial:[{period:'Month 1',receipts:15000,payments:18000},{period:'Month 2',receipts:18000,payments:14000},{period:'Month 3',receipts:20000,payments:16000}],fields:[num('opening','Opening cash',10000,-1e10,1e10),currency()],saveKey:'nepocore-cashflow-v1',label:'Forecast cash balances',note:'Forecasts are estimates. Record the timing of actual receipts and payments; unpaid sales are not cash receipts.',run:(data,v)=>{const r=cashFlow(v.opening,lines(data,['period','receipts','payments']));result(out,{label:'Final forecast balance',value:money(r.closing,v.currency),html:table(['Period','Opening','Receipts','Payments','Closing'],r.list.map(x=>[x.period,money(x.opening,v.currency),money(x.receipts,v.currency),money(x.payments,v.currency),money(x.closing,v.currency)])),note:r.list.some(x=>x.closing<0)?'At least one period has a negative forecast balance. Review timing and assumptions.':'Each period’s closing amount becomes the next period’s opening amount.'});exportCSV(out,r.list.map(x=>Object.fromEntries(Object.entries(x).map(([key,value])=>[key,typeof value==='number'?value/100:value]))),'nepocore-cash-flow.csv');}});}
